/**
 *
 * What are things someone will need to do for the Shadow Root stuff?
 *
 * 1. Create a shadow root on the element
 * 2. Render the react into the shadow root
 *   a. The react component should be wrapped in a div that looks like this
 *       <div neon-react-root dir={document.querySelector('html')?.getAttribute('dir') || undefined}>
 *          <ComponentToRender />
 *       </div>
 *
 * 3. Call applyNeonStylesToShadowDom to the shadow root element and save the returned unloadCallback
 * 4. When the MFE is unloaded, call the unloadCallback.
 */
/**
 * After creating a shadow-dom and rending a react app into it, use this function
 * to ensure that all neon web-components will be supported inside the shadow dom.
 * @param shadowRoot The shadow root to apply neon styles to
 * @returns An unload function. It is good to call this in the mfe unload function.
 */
export declare function applyNeonStylesToShadowDom(shadowRoot: ShadowRoot): () => void;
